/**
 * 智谱视觉识别设置初始化脚本
 * 在 DOM 完全加载后执行，设置事件监听器
 */
(function() {
    'use strict';
    
    // 等待 DOM 完全加载
    function initZhipuSettings() {
        // 延迟确保 settings.min.js 的初始化完成
        setTimeout(async function() {
            // 确保 ZhipuVision 已加载
            if (typeof ZhipuVision === 'undefined') {
                console.error('ZhipuVision 模块未加载');
                return;
            }
            
            // 加载智谱配置
            await ZhipuVision.loadConfig();
            var config = ZhipuVision.getConfig();
            
            var zhipuToggle = document.getElementById('zhipuToggle');
            var zhipuConfig = document.getElementById('zhipuConfig');
            var zhipuApiKey = document.getElementById('zhipuApiKey');
            var zhipuDefaultPrompt = document.getElementById('zhipuDefaultPrompt');
            var saveZhipuConfig = document.getElementById('saveZhipuConfig');
            var zhipuStatus = document.getElementById('zhipuStatus');
            
            // 检查元素是否存在
            if (!zhipuToggle || !zhipuConfig) {
                console.error('智谱设置元素未找到');
                return;
            }
            
            // 初始化开关状态
            if (config.enabled) {
                zhipuToggle.classList.add('active');
                zhipuConfig.style.display = 'block';
            }
            
            // 初始化表单值
            if (zhipuApiKey && config.apiKey) zhipuApiKey.value = config.apiKey;
            if (zhipuDefaultPrompt && config.defaultPrompt) zhipuDefaultPrompt.value = config.defaultPrompt;
            
            // 开关切换 - 使用事件监听器
            zhipuToggle.addEventListener('click', function(e) {
                e.preventDefault();
                e.stopPropagation();
                this.classList.toggle('active');
                zhipuConfig.style.display = this.classList.contains('active') ? 'block' : 'none';
            });
            
            // 保存配置
            if (saveZhipuConfig) {
                saveZhipuConfig.addEventListener('click', async function() {
                    var newConfig = {
                        enabled: zhipuToggle.classList.contains('active'),
                        apiKey: zhipuApiKey.value.trim(),
                        defaultPrompt: zhipuDefaultPrompt.value.trim() || '请详细描述这张图片的内容'
                    };
                    
                    await ZhipuVision.saveConfig(newConfig);
                    
                    zhipuStatus.className = 'status-message status-success';
                    zhipuStatus.textContent = '\u2713 智谱配置已保存';
                    zhipuStatus.style.display = 'block';
                    
                    setTimeout(function() {
                        zhipuStatus.style.display = 'none';
                    }, 3000);
                });
            }
            
            console.log('智谱设置初始化完成');
        }, 300);
    }
    
    // 兼容 DOMContentLoaded 事件
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initZhipuSettings);
    } else {
        // DOM 已经加载完成
        initZhipuSettings();
    }
})();
